-- GENERATED by `wfj generate` from data/gossip/gossip-6e.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["6e01b10f0177f497"] = { "Ah, e lo sciocco che mi ha liberato sarà tra i primi a placare la mia immensa fame.", "." },
  ["6e111eb4523ed287"] = { "%s è in preda allo stordimento...", "." },
  ["6e114cf220aad050"] = { "Puoi parlarmi di questo frammento?", "." },
  ["6e1440589fbde0e4"] = { "L'⟦Alliance=Alleanza⟧ ha completato le sue raccolte, {class}. Ora, mentre imballiamo e prepariamo tutto, attendiamo che l'Orda completi le sue. Poi trasporteremo tutti insieme il nostro materiale bellico a ⟦Silithus=Silitus⟧.", "." },
  ["6e14cc43fcc5fb38"] = { "Incredibili, vero? Tutti questi manufatti e resti.\n\nNon so cosa mi colpisca di più, le loro dimensioni o le storie che li accompagnano. C'è così tanto da studiare e imparare. E i collegamenti che possiamo fare...\n\nLo sapevi che si dice che molte razze abbiano le stesse origini degli elfi della notte?", "." },
  ["6e15ff6e05ea3ec9"] = { "Cosa, non riesci a teletrasportarti lì? Va' alla Darkbriar Lodge, vicino al lago nella ⟦Valley of Spirits=Valle degli Spiriti⟧, in alto e a ovest della ⟦Valley of Strength=Valle della Forza⟧.", "." },
  ["6e26a116d0b5c402"] = { "Renataki, delle ⟦Thousand Blades=Mille Lame⟧.\n\nIl dolore è la sua linfa vitale. La paura, la sua alleata. Possa un giorno tornare e portare con sé un gioioso spargimento di sangue.\n\nOra Renataki dimora lontano da qui. Un giorno, forse, tornerà...", "." },
  ["6e2bac745ea7087c"] = { "Abbiamo qualche rifornimento, ma non molti. Ce ne serviranno molti di più per lanciare un assalto via terra nel ⟦Field of Strife=Pian della Discordia⟧.", "." },
  ["6e2d61616829a931"] = { "Mi metto subito al lavoro, {name}!", "." },
  ["6e392578c1ec75ef"] = { "Il tuo nome sarà ricordato nei secoli, {name}. Cerca ⟦Taim Ragetotem=Taim Totem Rabbioso⟧ sull'⟦Hunter Rise=Altura dei Cacciatori⟧: ti aiuterà a raggiungere la ⟦Alterac Valley=Valle d'Alterac⟧.", "." },
  ["6e3cc1f93427a4ba"] = { "Hai certamente fatto molta strada nel tuo addestramento. C'è un solo istruttore che può addestrarti ancora. Trova ⟦Buzzek Bracketswing=Buzzek Forcatorta⟧ a ⟦Gadgetzan=Meccania⟧!", "." },
  ["6e443221011c62ce"] = { "Per l'⟦Alliance=Alleanza⟧!", "." },
  ["6e4597f8b9786582"] = { "C'è una certa simmetria nell'idea che la pelle del tuo nemico ti dia protezione. Per migliorare le tue abilità di conciatura, cerca ⟦Una=Uma⟧ dagli armaioli di ⟦Thunder Bluff=Picco del Tuono⟧, sull'altura di mezzo.", "." },
  ["6e49cde3ac16a48e"] = { "Hai la mia parola che troverò un uso per il tuo corpo dopo averti ucciso, {race}.", "." },
  ["6e6bfc9a28f39e66"] = { "Una maledizione? Cosa succede qui, Fairbanks?", "." },
  ["6e708352e756f41c"] = { "Ti evoco, ⟦Sha'ni Proudtusk=Sha'ni Zannafiera⟧!", "." },
  ["6e7159f354f8ec59"] = { "Salute. Insegno agli stregoni, ma tu non sei <uno/una> <stregone/strega>!", "." },
  ["6e71bef2a3b7686b"] = { "Ci sarà di sicuro uno gnomo a ⟦Stormwind=Roccavento⟧ che può insegnarti la professione. Di certo una delle guardie di ⟦Stormwind=Roccavento⟧ saprà indicarti la direzione giusta.", "." },
  ["6e77023504d95a88"] = { "Ti addestrerei se potessi, ma sei troppo per me. Facciamo così: va' a parlare con la tauren ⟦Una=Uma⟧ nelle botteghe a nord-ovest dell'altopiano centrale di Picco del Tuono. Ha un vero talento.", "." },
  ["6e77c0a32083f24c"] = { "Oh, intendi Johnson? Ho sentito che si nasconde.", "." },
  ["6e7a9f59aed08c4d"] = { "La flotta è pronta, {name}. Prendi questo segnalatore e piazzalo nel cratere orientale della zona di battaglia centrale. Difendilo dagli assalitori finché la flotta non riesce ad agganciarne le coordinate!", "." },
  ["6e7e8ddcae7cd663"] = { "Che cosa farò?", "." },
  ["6e7fe384655d5a70"] = { "L'unica cosa che Metzen farà in questo Grande Inverno sarà arrostire allo spiedo!", "." },
  ["6e86f52afa1e3b07"] = { "La ⟦Irondeep Mine=Miniera di Ferrofondo⟧ è in territorio dell'⟦Alliance=Alleanza⟧, a nord del ⟦Stormpike Graveyard=Cimitero dei Piccatonante⟧.\n\nÈ controllata dai trogg.", "." },
  ["6e89e13e9b48dd20"] = { "Ma ti temono e ti odiano, Danitha. Lo sai di certo, no? Nell'⟦Argent Dawn=Alba d'Argento⟧ il tuo legame con la Luce sarebbe una risorsa. Saresti tenuta in grande considerazione!", "." },
  ["6e8e7c0787e23bb7"] = { "Ooh, è proprio bello! Lascia che lo dissotterri...", "." },
  ["6e8f995c9266f2e5"] = { "Non offro addestramento per apprendisti. Cerca il tauren Waldor nella ⟦Wailing Caverns=Caverna dei Lamenti⟧, qui nelle ⟦Barrens=Savane⟧. Può aiutarti con qualsiasi cosa ti serva.", "." },
  ["6e909972f5cfe8d9"] = { "Ehi, Hornizz! Eccomi di ritorno! E dietro di me c'è gente che mi ha tirato fuori dai guai.", "." },
  ["6e9267c79f4d0909"] = { "Oggi non si mette bene. Il sole è alto e forte già di buon'ora, e sull'acqua non si muove niente.", "." },
  ["6e9abdec8d3bb3bc"] = { "<Bentornato/Bentornata> al più grande spettacolo di Azeroth, <amico/amica> <mio/mia>! È davvero una gioia rivederti.\n\nPrego, fatti avanti e goditi ancora una volta tutto ciò che abbiamo da offrire. Guardati bene attorno, perché aggiungiamo sempre cose nuove ed entusiasmanti alla ⟦Darkmoon Faire=Fiera di Lunacupa⟧! Lasciati stupire dalle meraviglie, vecchie e nuove, che abbiamo scoperto! Continuiamo a non badare a spese per offrirti emozioni che delizieranno i bambini di tutte le età!", "." },
  ["6e9d7ddae9a66725"] = { "%s sente la voce del suo padrone!", "." },
  ["6ea555c0f19acfa5"] = { "Eh? Hai affari con Nimboya?", "." },
  ["6ea647bddde9355f"] = { "Il Capoguerra farà presto i conti con voi, mortali. Preparatevi!", "." },
  ["6ea944b62f6ff84c"] = { "Siate testimoni del potere innegabile del vostro Capoguerra! Lasciatevi sollevare dal grido di battaglia dei vostri ammazzadraghi!", "." },
  ["6eab780790426016"] = { "⟦Desolace=Desolanda⟧ non è poi un posto così brutto, se non ti danno fastidio le continue molestie dei centauri.", "." },
  ["6ead34df05664eb3"] = { "%s va su tutte le furie!", "." },
  ["6eb2960511f6ea81"] = { "Forse dovremmo andare a pescare sul ponte.", "." },
  ["6eb52fab11eac6fe"] = { "Fermarsi: no. Rallentare: forse.\n\nScholomance è la loro principale fonte di addestramento e istruzione. È da lì che i membri del culto si sparpagliano e alla fine si infiltrano nelle nostre società.\n\nPer questo dobbiamo colpire alla fonte. Il cuore stesso del Cult of the Damned!", "." },
  ["6ebcae1ae7142c2e"] = { "Perché sta succedendo? In poche parole, gli spiriti del vento sono... svaniti. \r\n\nI piccoli folletti e gli elementali minori che probabilmente hai incontrato là fuori sono una pallida imitazione dei veri spiriti del vento. Privi di coscienza, senza meta, e ben lontani dagli spiriti benevoli accanto ai quali abbiamo vissuto in armonia per migliaia di anni.", "." },
  ["6ebdd935772ef37a"] = { "Le tue abilità sono oltre la mia portata. È ora che tu affronti nuove sfide. Taladan ti aiuterà a prepararti. È là, vicino al tavolo.", "." },
  ["6ec6b7fb4926c693"] = { "Se cerchi un'attività davvero gratificante, una vita dedicata all'incantamento fa per te!", "." },
  ["6ed8c284491135c1"] = { "Di' al direttore che ora questa prigione è nostra!", "." },
  ["6edb42d5d7a22ac8"] = { "Cyndra non sarà frizzante come le sue pozioni, ma i suoi modi gentili sono adatti a insegnare il mestiere. La trovi appena a est della locanda di Dolanaar.", "." },
  ["6eddabd2707bec3e"] = { "Il mastro artigiano Omarion è svanito una notte. Come un peto al vento... Puf! Sparito! Bah, ora resto solo io a fabbricare la roba per i ragazzi al fronte.", "." },
  ["6ee81efe6788ba3d"] = { "Nessuno può resistere ai Serpent Lords!", "." },
  ["6eea63550b5d2185"] = { "Che combattimento eccezionale! Hai reso orgoglioso un vecchio. Continua così e stasera la birra la offro io.", "." },
  ["6eec29471dc66aad"] = { "{name} conquista la miniera! Se nessuno interviene, l'⟦Alliance=Alleanza⟧ la controllerà fra 1 minuto!", "." },
  ["6ef65b28b744c712"] = { "Le tue misere magie non sono nulla contro la potenza del Flagello!", "." },
  ["6efc4fee75d5bab6"] = { "Eh eh! Questo sarà un ottimo nascondiglio.", "." },
})
